// Each study keeps its original input/state controller, with a new authored visual composition.
const Atelier={paper:'#eee9df',ink:'#30423e',muted:'#75847b',green:'#6b9987',gold:'#c6aa74',night:'#142427',white:'#faf6ec'};
function label(c,t,x,y,size=12,color=Atelier.ink,align='left',serif=false){
 t=atlasText(t);if(/[\u4e00-\u9fff]/.test(t))serif=false;
 if(c._compact){if(size<10&&c._study!==26)return;size=Math.max(size,10/Math.max(.35,c._cssScale||.5));}
 if(c._dark&&c._theme&&!c._theme.dark&&['#e9eee2','#9eb3a7','#bfd0af','#d7dec1','#a3c9ad','#d6b98b'].includes(color))color=c._theme.ink;
 c.save();clearShade(c);c.fillStyle=color;c.font=`${serif?'italic ':''}${size}px ${serif?'Georgia,serif':'-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif'}`;c.textAlign=align;c.textBaseline='middle';c.fillText(t,x,y);c.restore();
}
function grad(c,x,y,w,h,stops){const g=c.createLinearGradient(x,y,x+w,y+h);stops.forEach(([a,b])=>g.addColorStop(a,b));return g}
function shade(c,blur=22,y=8,color='#10232130'){c.shadowColor=color;c.shadowBlur=blur;c.shadowOffsetY=y}
function clearShade(c){c.shadowColor='transparent';c.shadowOffsetY=0;c.shadowBlur=0}
function disc(c,x,y,r,base,hi='#ffffff',dark='#24453c'){const g=c.createRadialGradient(x-r*.35,y-r*.45,r*.05,x,y,r);g.addColorStop(0,hi);g.addColorStop(.28,base);g.addColorStop(1,dark);circle(c,x,y,r,g)}
function oval(c,x,y,rx,ry,fill){c.beginPath();c.ellipse(x,y,rx,ry,0,0,TAU);c.fillStyle=fill;c.fill()}
function pill(c,x,y,w,h,fill,stroke){rr(c,x,y,w,h,h/2,fill,stroke)}
function surface(c,x,y,w,h,r=15,fill=Atelier.white){c.save();shade(c,24,10);rr(c,x,y,w,h,r,fill);c.restore();rr(c,x+.5,y+.5,w-1,h-1,r,undefined,'#ffffff60')}
const paintingCache=new Map();
function painting(id){const key=((id%8)+8)%8;if(paintingCache.has(key))return paintingCache.get(key);const cv=document.createElement('canvas');cv.width=720;cv.height=960;const c=cv.getContext('2d');
 const sets=[['#d6cbb4','#9eaaa0','#4c7978','#e2c1a0'],['#dfd8c1','#79957f','#324d47','#e5bca2'],['#e9cabe','#ad8792','#5b5968','#f3d4ae'],['#afc4cb','#718f9a','#274958','#e4d5bb'],['#e9d6b6','#b5ab85','#686c53','#f1e4c9'],['#c3d3c6','#68998e','#2b5b55','#e1c493'],['#cdc5ce','#9285a2','#514d65','#e7c0a3'],['#e4d2c3','#a19586','#494f49','#dfb68f']];const [sky,ridge,deep,sun]=sets[key];
 c.fillStyle=grad(c,0,0,0,960,[[0,sky],[.6,'#f2e7d1'],[1,ridge]]);c.fillRect(0,0,720,960);circle(c,490,228,82,sun);
 for(let layer=0;layer<7;layer++){c.beginPath();c.moveTo(-50,960);for(let j=0;j<=110;j++){const u=j/110,yy=410+layer*66+Math.sin(u*(3+key*.4)+layer*.6)*80+Math.sin(u*12+layer)*12;c.lineTo(u*820-50,yy)}c.lineTo(800,960);c.closePath();c.fillStyle=layer<2?ridge:deep;c.globalAlpha=.25+layer*.085;c.fill()}c.globalAlpha=1;
 // Fine strokes describe a coastal inlet, with depth in the reflection.
 c.save();c.beginPath();c.moveTo(200,610);c.bezierCurveTo(450,590,600,760,720,750);c.lineTo(720,960);c.lineTo(15,960);c.bezierCurveTo(105,790,200,790,200,610);c.clip();c.fillStyle=grad(c,0,600,0,360,[[0,ridge],[1,sky]]);c.fillRect(0,600,720,360);for(let i=0;i<160;i++){const yy=620+i*2.2,xx=hash(i+key)*700;line(c,[[xx,yy],[xx+15+hash(i)*75,yy]],i%3?'#ffffff28':sun+'80',.8)}c.restore();
 // Foreground grasses and printed texture give every artwork a usable high-resolution surface.
 for(let i=0;i<60;i++){const xx=hash(i+key*20)*165,yy=860+hash(i+33)*100;c.strokeStyle=deep+'a0';c.lineWidth=1.5;c.beginPath();c.moveTo(xx,960);c.quadraticCurveTo(xx-10,yy+40,xx+hash(i+11)*30-15,yy);c.stroke()}
 c.globalAlpha=.035;for(let i=0;i<18000;i++){c.fillStyle=i%2?'#ffffff':'#102721';c.fillRect(hash(i)*720,hash(i+80)*960,1,1)}c.globalAlpha=1;
 paintingCache.set(key,cv);return cv;
}
art=function(c,id,x,y,w,h){c.save();c.beginPath();c.rect(x,y,w,h);c.clip();const img=painting(id),scale=Math.max(w/img.width,h/img.height),dw=img.width*scale,dh=img.height*scale;c.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);c.restore()};
texture=function(id){return painting(id)};
quadArt=function(c,id,pts,alpha=1){const img=texture(id);c.save();c.globalAlpha=alpha;triangle(c,img,[[0,0],[720,0],[720,960]],[pts[0],pts[1],pts[2]]);triangle(c,img,[[0,0],[720,960],[0,960]],[pts[0],pts[2],pts[3]]);c.restore();line(c,[...pts,pts[0]],'#fff8',.6)};
function photo(c,id,x,y,w,h,angle=0){c.save();c.translate(x+w/2,y+h/2);c.rotate(angle);shade(c,18,8);rr(c,-w/2-6,-h/2-6,w+12,h+25,2,'#fffaf0');clearShade(c);art(c,id,-w/2,-h/2,w,h);label(c,['COAST / 01','FOREST / 02','DUSK / 03','TIDE / 04'][((id%4)+4)%4],-w/2+4,h/2+10,7,'#8a9388');c.restore()}
function stageBase(c,id,dark=false){c._dark=dark;const palette=c._theme;
 c.fillStyle=palette?grad(c,0,0,600,360,[[0,palette.top],[1,palette.base]]):dark?grad(c,0,0,0,360,[[0,'#101e22'],[1,'#263c3c']]):grad(c,0,0,600,360,[[0,'#f3eee5'],[1,'#e1dfd2']]);
 c.fillRect(-(c._extraX||0),-(c._extraY||0),600+2*(c._extraX||0),360+2*(c._extraY||0));glow(c,435,20,350,palette?.dark?'#ffffff06':'#ffffff35');
}
function heading(c,title,kicker,dark=false){if(c._theme){c._heading=atlasText(title);return;}label(c,kicker,34,27,8,dark?'#a3b8b0':'#859087');label(c,title,34,52,25,dark?'#e9eee2':Atelier.ink,'left',true)}
function note(c,t,dark=false){if(c._compact&&c._study===26)return;label(c,t,300,337,9,dark?'#9eb3a7':'#7c8d7d','center')}
function ring(c,x,y,r,color,width=1,a=0,b=TAU){c.beginPath();c.arc(x,y,r,a,b);c.strokeStyle=color;c.lineWidth=width;c.stroke()}
function gardenFlower(c,x,y,r,age,start,petal){
 const bud=out((age-start+.3)/.3),open=ease((age-start)/.85);
 if(!bud)return;
 c.save();c.translate(x,y);c.scale(bud,bud);
 // The closed bud opens into separately staggered, cupped petals.
 oval(c,0,2,4,7*(1-open)+3,'#749064');
 for(let i=0;i<7;i++){
  const q=ease((age-start-i*.024)/.68);
  c.save();c.rotate(i/7*TAU-.18);c.scale(.18+.82*q,.28+.72*q);
  c.beginPath();c.moveTo(-2,0);
  c.bezierCurveTo(-r*.75,-r*.55,-r*.45,-r*1.25,0,-r);
  c.bezierCurveTo(r*.5,-r*1.22,r*.7,-r*.45,2,0);
  c.closePath();c.fillStyle=grad(c,-r*.35,-r,r*.7,r,[[0,'#fff9ed'],[.45,petal],[1,'#bb958277']]);
  c.fill();c.strokeStyle='#fff9e866';c.lineWidth=.5;c.stroke();
  if(q>.35)line(c,[[0,-r*.25],[0,-r*.75]],'#fff7e955',.5);
  c.restore();
 }
 disc(c,0,0,3.5+open*1.5,'#c8a15a','#f8e7b2','#a87c40');
 for(let i=0;i<9;i++){const a=i/9*TAU;circle(c,Math.cos(a)*3*open,Math.sin(a)*3*open,.6,'#fff0be');}
 c.restore();
}
